package redact

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// The corpus is generated by scripts/gen-redact-phone-corpus.mjs from the TS redactor and
// shared with packages/sync/src/redact.test.ts: both languages must produce exactly the
// committed output, and no phone digit string may survive in either.
const corpusPath = "../../../packages/sync/src/__fixtures__/redact-phone-corpus.json"

func TestPhoneCorpus(t *testing.T) {
	raw, err := os.ReadFile(corpusPath)
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	var file struct {
		Cases []struct {
			Input       string   `json:"input"`
			PhoneDigits []string `json:"phoneDigits"`
			Expected    string   `json:"expected"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &file); err != nil {
		t.Fatalf("parse corpus: %v", err)
	}
	if len(file.Cases) < 1500 {
		t.Fatalf("corpus holds %d cases, want at least 1500", len(file.Cases))
	}
	strip := strings.NewReplacer(" ", "", "\t", "", ".", "", "-", "", "–", "", "—", "", "/", "", "(", "", ")", "", " ", "")
	bad := 0
	for _, c := range file.Cases {
		out := String(c.Input, Logs)
		if out != c.Expected {
			bad++
			if bad <= 5 {
				t.Errorf("output %q -> %q, want %q", c.Input, out, c.Expected)
			}
		}
		stripped := strip.Replace(out)
		for _, d := range c.PhoneDigits {
			if strings.Contains(stripped, d) {
				bad++
				if bad <= 5 {
					t.Errorf("leak %q -> %q (digits %s)", c.Input, out, d)
				}
			}
		}
	}
	if bad > 0 {
		t.Fatalf("%d corpus failures", bad)
	}
}
